\section{Application 1: QFT for \texorpdfstring{$\GL_2(\mathbb{F}_q)$}{GL2(Fq)}}\label{sec: GL2}

An application of the induced transform using Mackey theory is QFT for the group of invertible $2 \times 2$ matrices over a finite field. Let $q=p^r$ be a prime power and consider the group $G:=\GL_2(\F_q)$. The main result is the following theorem.

\begin{theorem}[QFT for $\GL_2(\F_q)$]\label{thm: GL2 QFT}
	For every $\varepsilon>0$, there exists a uniform quantum circuit of size $\operatorname{poly}\left(\log q, \log \frac{1}{\varepsilon}\right)$ that implements the QFT of $\GL_2(\F_q)$ to operator-norm error at most $\varepsilon$.
\end{theorem}

We prove this theorem by induction along the chain
\begin{equation}\label{eq: subgroup chain}
	\{\I\} \subset T \subset B \subset \GL_2(\F_q),
\end{equation}
where $T$ consists of diagonal matrices and $B$ of upper triangular ones.  First, in \cref{sec: rep theory of GL2} we describe the representation theory of the subgroup chain \eqref{eq: subgroup chain}. Then in \cref{subsec: sub_adap bases} we give explicit formulas for each representation in the Gelfand--Tsetlin basis, and in \cref{sec: twiddle factors} compute matrix coefficients for transversal actions.
Finally, in \cref{sec: GL2 QFT circuit} we construct the $\GL_2(\F_q)$ QFT quantum circuit using the Mackey approach which we introduced in \cref{sec: Mackey transform}. The hardest part in this circuit is the $A$-matrix, which contains a $q\times q$-block that is constructed in \cref{subsec: polylog GL2 A}.

\begin{remark}
	See \cref{app: finite fields} for an introduction to finite fields. We often use an isomorphism $X_q:= \widehat{\F_q^*} \cong \F_q^*$ that allows us to interpret character labels as invertible field elements. This is done throughout this section. Note that the isomorphism is non-canonical and depends on the choice of generator of $\F_q^*$.
\end{remark}

\subsection{Representation theory of \texorpdfstring{$\GL_2(\F_q)$}{GL2(Fq)} and subgroups}\label{sec: rep theory of GL2}

We give an overview of the representation theory of $G$ and its Borel subgroup $B$.
This section mostly follows \cite{Piatetski1983complex}. Other sources on the representation theory of $\GL_2(\F_q)$ are \cite{prasad2007representations, LiNote} (also containing explicit constructions) and \cite[chapter 2]{bushnell2006Langlands} (which is a more concise overview).

Define the following subgroups and elements of $G$:
\begin{align}
	B &:= \{\psm{
		a&b\\0&d
	} \in G\}\quad &&(\text{Borel subgroup}), \label{eq: B}\\
	U &:=  \{\psm{
		1&b\\0&1
	} \in G\} &&(\text{unipotent/normal subgroup of $B$}),\\
	T&:= \{\psm{
		a&0\\0&d
	} \in G\} &&(\text{split maximal torus in } G),\\
	Z&:= \{\psm{
		a&0\\0&a
	} \in G\} &&(\text{the center of $G$}),\\
	P&:= \{\psm{a&b\\0&1}\in G\}.
\end{align}
Also define the following two group elements:
\begin{equation*}
	w:= \psm{
	0&1\\1&0
} \quad (\text{Weyl representative, }w^2=\I), \qquad
	w':= \psm{
	0&1\\-1&0
} .
\end{equation*}
There is a semidirect product decomposition $B = T \ltimes U$. Moreover, $G$ satisfies a Bruhat decomposition
\begin{equation}\label{eq: Bruhat decomposition}
	G  = B~W~B, \quad W=\{\I, w\},
\end{equation}
where $W$ is known as the \emph{Weyl group}.

\subsubsection{Irreducible representations of $B$ and $G$}\label{subsec: B G irreducibles}

The Borel subgroup $B\subset G$ has the following representations.

\paragraph{One-dimensional}
Let $\alpha, \beta \in X_q$ label two characters $\chi_{\alpha}, \chi_{\beta}$ of $\F_q^*$. We combine them to create a character on $T$ via $\chi_{\alpha,\beta}(\psm{a&0\\0&d})=\chi_\alpha(a)\chi_\beta(d)$.
We extend this character trivially to $U$ to obtain the one-dimensional representation of $B$
\begin{equation}\label{eq: one-dim B}
	\chi_{\alpha, \beta}\psm{a&b\\0&d}
    =\chi_{\alpha}(a)\chi_{\beta}(d).
\end{equation}

\paragraph{Higher-dimensional}
Consider the representation $\rho$ of $P=\{\psm{a&b\\0&1}: a\in \F_q^*, b\in \F_q\}$ acting on  $\C[\F_q^*]$ via
\begin{equation}\label{eq: rho on P}
	\rho\psm{a&b\\0&1} \: \ket{x} = \psi(\frac{b}{a}x)\ket{\frac{1}{a}x}.
\end{equation}
We extend $\rho$ to $B$ by picking a multiplicative character $\chi_\gamma$ and defining $\rho_{\gamma}\psm{d&0\\0&d}\ket{x} = \chi_{\gamma} (d)\ket{x}$. The total action on $B = Z  \times P$ is then
\begin{equation}\label{eq: rho_gamma action}
	\rho_{\gamma}\psm{a&b\\0&d}\ket{x} = \rho_{\gamma}\left(\psm{d&0\\0&d}\psm{a/d & b/d\\0&1} \right)\ket{x}  =  \chi_{\gamma}(d)\psi(\frac{b}{a}x) \ket{\frac{d}{a}x}.
\end{equation}

\begin{remark}
	The representation $\rho$ of $P$ can be obtained in the following way. View $\psi \in \widehat{\F_q^+}$ as a character on $U = \{\psm{1&b\\0&1}: b\in \F_q\}$. Induce this character to $P$ to obtain a $(q-1)$-dimensional representation $\rho'$. A transversal set of $P/U$ is given by $\{\psm{x&0\\0&1}: x\in \F_q^*\}$.
	The induced representation is then given by
	\begin{equation}
		\rho'\psm{a&b\\0&1}\ket{x} = \psi(\frac{b}{ax})\ket{ax}.
	\end{equation}
	Intertwining with the map $(\ket{x}\mapsto \ket{1/x})$ gives an equivalence between $\rho'$ and $\rho$.
\end{remark}
The irreducible representations of $G$ are classified as follows.

\paragraph{Principal series}
The representations of $B$ can be extended to $G$ by \emph{parabolic induction}. For $\alpha,\beta\in X_q$ we induce $\chi_{\alpha,\beta}$ from $B$ to $G$ to obtain the \emph{principal series} representation. The construction is as follows. We choose a transversal set of $G/B$ to be
\begin{equation}\label{eq: transversal set G/B}
	\{t_x: x\in \F_q\}\cup \{t_{\infty}\}:=\{\psm{x&1\\1&0}: x\in \F_q\} \cup \{\psm{1&0\\0&1}\}.
\end{equation}
The set of transversals can be identified with $\P^1(\F_q)$, a projective copy of $\F_q$. In particular, they satisfy the following: for any $g=\psm{a&b\\c&d} \in G$,
\begin{align}
	g \cdot t_x &=
	\begin{cases}
		t_{gx}\cdot\psm{cx+d &c\\0 & \frac{\det(g)}{cx+d}} &\text{ if } cx+d\neq0\\
		t_{\infty} \cdot \psm{ax+b &a \\0&c} &\text{ if } cx+d=0,
	\end{cases}\label{eq: g action projective 1}\\
	g \cdot t_{\infty} &=
	\begin{cases}
		t_{a/c}\cdot \psm{c&d\\0&\frac{-\det(g)}{c}} &\text{ if } c\neq 0\\
		t_{\infty} \cdot \psm{a&b\\0&d} &\text{ if } c=0.
	\end{cases}\label{eq: g action projective 2}
\end{align}
By $gx\in \P^1(\F_q)$ we mean the standard action of $\GL_2(\F_q)$ on the projective line, given by $\psm{a&b\\c&d}x = \frac{ax+b}{cx+d}$. In particular, it holds that $g\cdot t_{x} = t_{gx} \cdot b_x^g$ for all $x\in \P^1(\F_q)$, where $b_x^g\in B$. Thus, the principal series representation acting on the space $\C[\P^1(\F_q)]$ is given by
\begin{equation} \label{eq: full chi_ab action}
	I_{\alpha, \beta} \psm{a&b\\c&d}\ket{x} = \chi_{\alpha, \beta}(b_x^g) \ket{gx},
\end{equation}
where the term $b_x^g$ is given by \cref{eq: g action projective 1,eq: g action projective 2}.
Conveniently, the principal series is irreducible, except when $\alpha =\beta$.
\begin{lemma}
	The principal series $I_{\alpha, \beta}$ is irreducible whenever $\alpha\neq\beta$. Otherwise, it splits into a one-dimensional and a Steinberg representation. Moreover, $I_{\alpha,\beta}$ and $I_{\gamma, \delta}$ are isomorphic if and only if $[\alpha = \gamma,~\beta=\delta]$ or $[\alpha=\delta,~\beta = \gamma]$.
\end{lemma}

\paragraph{Steinberg and determinant representations}
Whenever $\alpha=\beta$ in the principal series representation, it splits into two irreducible parts of dimensions $1$ and $q$. They are called the \emph{(twisted) determinant and Steinberg representation} respectively.

Following \cref{eq: full chi_ab action}, the action of $I_{\alpha, \alpha}$ on the standard basis of $\C[\P^1(\F_q)]$ is given by
\begin{align}
	I_{\alpha, \alpha} (g) \ket{x} &= \begin{cases}
		\chi_{\alpha}(\det(g))\ket{gx} &\text{ if } gx\neq \infty\\
		\chi_{\alpha}(-1)\chi_{\alpha}(\det(g))\ket{\infty} & \text{ if }gx = \infty
	\end{cases}\quad \text{ for } x\in \F_q, \\
	I_{\alpha, \alpha} (g) \ket{\infty} &= \begin{cases}
		\chi_{\alpha}(-1)\chi_{\alpha}(\det(g))\ket{g\infty} &\text{ if } g\infty\neq \infty\\
		\chi_{\alpha}(\det(g))\ket{\infty} & \text{ if }g\infty = \infty.
	\end{cases}
\end{align}
It follows that the vector
\begin{equation}\label{eq: v}
	\ket{v}:= \frac{1}{\sqrt{q+1}}\left(\chi_{\alpha}(-1) \ket{\infty} + \sum_{x\in \F_q}\ket{x}\right)
\end{equation}
spans a one-dimensional subspace with the action given by
\begin{equation}\label{eq: determinant action on v}
	(\chi_\alpha \circ \det) g\ket{v} = \chi_{\alpha}(\det(g)) \ket{v}.
\end{equation}
This we call the (twisted) determinant representation and we denote it by $\det_{\alpha}$. The orthogonal complement is called the Steinberg representation and is denoted by $\St_{\alpha}$.

\paragraph{Cuspidal representations}
Any irreducible representation that is not part of an induction from the Borel subgroup is called \emph{cuspidal}. A construction is presented in \cite[section 13]{Piatetski1983complex}. Using the Bruhat decomposition \eqref{eq: Bruhat decomposition} we only have to specify the cuspidal on $B$ and the element $w'\in G$, with the remark that $w = w'\psm{-1&0\\0&1}$.

The cuspidal representations are denoted by $\pi_{\theta}$ and indexed by Frobenius orbits $\{\theta,\theta^q\}$ of regular characters $\theta\in X_{q^2}$, where $\theta^q\neq\theta$ and $\pi_\theta\simeq\pi_{\theta^q}$.
Let $\gamma$ satisfy $\theta|_{\F_q^*}=\chi_\gamma$.  The cuspidal representation $\pi_\theta$ acts on $\C[\F_q^*]$ by
\begin{equation}\label{eq: cuspidal action}
	\pi_{\theta}\psm{a&b\\0&d} \ket{x}
    =\chi_{\gamma}(d) \psi(\frac{b}{a}x) \ket{\frac{d}{a}x},
\end{equation}
and
\begin{equation}\label{eq: cuspidal w prime}
	\pi_{\theta}(w')\ket{x}
    =\theta(x^{-1}) \sum_{y\in \F_q^*}j_\theta(yx)\ket{y},
    \qquad
    j_\theta(u)=-\frac{1}{q}\sum_{\substack{v\in \F_{q^2}^*\\ \No(v)=u}}
    \psi(\tr(v))\theta(v),
\end{equation}
where $\tr$ and $\No$ denote the finite field trace and norm, see \cref{eq: tr,eq: N} in \cref{app: finite fields}.

The set of all irreps of $G$ is summarized in the table below.
\[\begin{array}{c|c|c|c}
	\text{label of irrep}&\text{name}&\text{dimension}& \text{\# irreps of this type}\\
    \hline
	\chi_{\alpha} \circ\det& \text{determinant} &1&q-1\\
	\hline
	\St_{\alpha} & \text{Steinberg} &q&q-1\\
	\hline
	I_{\alpha,\beta}&\text{principal} &q+1&\frac{(q-1)(q-2)}{2}\\
	\hline
	\pi_{\theta}&\text{cuspidal}&q-1&\frac{q(q-1)}{2}
	\end{array}
\]
The sum of their squared dimensions
\begin{equation*}
    (q-1)\cdot 1^2 + (q-1)\cdot q^2 + \frac{(q-1)(q-2)}{2} \cdot (q+1)^2 + \frac{q(q-1)}{2}\cdot (q-1)^2 = (q^2-1)(q^2-q) = |G|
\end{equation*}
tells us that these are all the irreducible representations of $G$.

\subsection{Gelfand--Tsetlin bases for \texorpdfstring{$\GL_2(\F_q)$}{GL2(Fq)}}\label{subsec: sub_adap bases}
The irreducible representations of $B$ and $G$ are listed in \cref{subsec: B G irreducibles}. For completeness we note the ones of $T$ as well.
\begin{lemma}
    All the irreducible representations of $T$ are one-dimensional and given by
    \begin{equation}
        \chi_{\alpha, \beta}\psm{a&0\\0&d} = \chi_{\alpha}(a)\chi_{\beta}(d)
    \end{equation}
     with $\alpha,\beta\in X_q$, creating a total of $(q-1)^2$ characters.
\end{lemma}

\begin{lemma}\label{lem: decomposition of restrictions}
    The following restrictions of irreducible representations hold:
    \begin{align}
        \Res_T^B\chi_{\alpha,\beta}
        &=\chi_{\alpha,\beta},\\
        \Res_T^B\rho_\gamma
        &=\bigoplus_{\delta\in X_q}
          \chi_{\delta,\delta^{-1}\gamma},\\
        \Res_B^G\det_\alpha
        &=\chi_{\alpha,\alpha},\\
        \Res_B^G\St_\alpha
        &=\chi_{\alpha,\alpha}\oplus\rho_{\alpha^2},\\
        \Res_B^G I_{\alpha,\beta}
        &=\chi_{\alpha,\beta}\oplus\chi_{\beta,\alpha}
          \oplus\rho_{\alpha\beta},\qquad \alpha\neq\beta,\\
        \Res_B^G\pi_\theta
        &=\rho_\gamma,
        \qquad \theta|_{\F_q^*}=\chi_\gamma.
    \end{align}
    In particular, restriction along the chain $T\subset B\subset\GL_2(\F_q)$ is multiplicity-free.
\end{lemma}
\begin{proof}
    All these relations can be checked by taking inner products of characters and/or using Mackey decomposition in \cref{lemma: Mackey}.
\end{proof}

Now that we know the restrictions are multiplicity free, we need to find subgroup-adapted bases for each irreducible representation of $G$.

\subsubsection{From $T$ to $B$}\label{sec: T2B}

We need to study the restriction of $\rho_{\gamma}$ to $T$. By \cref{eq: rho_gamma action}, it follows that $\Res_T^B \rho_{\gamma} \psm{a&0\\0&d}$ equals a permutation matrix $\{x \mapsto \frac{d}{a}x\}$ and a global scaling by $\chi_{\gamma} (d)$. To diagonalize this matrix, consider the multiplicative Fourier basis given by
\begin{equation}\label{eq: mult fourier basis}
    \ket{w_{\delta}} := \frac{1}{\sqrt{q-1}} \sum_{x\in \F_q^*} \chi_{\delta}(x) \ket{x} \text{ for all } \delta\in \F_q^*.
\end{equation}
The action of $\rho_{\gamma}$ restricted to $T$ is then diagonalized and given by
\begin{align*}
    \rho_{\gamma} \psm{a&0\\0&d} \ket{w_\delta} &= \frac{1}{\sqrt{q-1}} \sum_{x\in \F_q^*} \chi_{\gamma}(d) \chi_\delta(x) \ket{\frac{d}{a}x} = \chi_{\gamma}(d)\frac{1}{\sqrt{q-1}}\sum_{y\in \F_q^*} \chi_\delta(\frac{a}{d}y) \ket{y}\\
    &=\chi_{\gamma}(d)\chi_{\delta}(\frac{a}{d}) \ket{w_\delta} = \chi_{\delta}(a)\chi_{\delta^{-1}\gamma}(d) \ket{w_\delta}.
\end{align*}

\subsubsection{From $B$ to $G$}

\paragraph{Principal series} We start by studying the principal series representation $I_{\alpha, \beta}$.  Recall by \cref{lem: decomposition of restrictions} that the restriction to $B$ needs to give two one-dimensional subspaces and one space of dimension $q-1$. The basis used in \cref{eq: full chi_ab action} gives a permutation of the basis elements by $x\mapsto \frac{ax+b}{d}$, which is sparse but not subgroup adapted. The permutation, as in \cref{sec: T2B}, directs us toward the Fourier basis.
\begin{itemize}
    \item Note that $B$ is the stabilizer of $\infty$ under the standard action. Therefore $\ket{\infty}$ spans an invariant subspace such that
    \begin{equation*}
        I_{\alpha, \beta} (g) \ket{\infty } = \chi_{\alpha, \beta}(g)\ket{\infty} \quad \text{ for all } g\in B.
    \end{equation*}
    \item Consider the additive (inverse) Fourier basis of $\F_q$ given by
    \begin{equation*}
        \ket{v_{t}}:= \frac{1}{\sqrt{q}}\sum_{x\in \F_q} \overline{\psi(tx)} \ket{x} \quad \text{ for all } t\in \F_q.
    \end{equation*}
    The action of $B$ on this basis is given by
    \begin{align}\label{eq: principal series on basis}
        I_{\alpha, \beta} \psm{a&b\\0&d} \ket{v_t}
        &= \frac{1}{\sqrt{q}} \sum_{x\in \F_q} \chi_{\alpha}(d) \chi_{\beta}(a) \overline{\psi(tx)} \ket{\frac{ax+b}d} \nonumber\\
        &= \chi_{\beta}(a) \chi_{\alpha}(d) \frac{1}{\sqrt{q}} \sum_{y\in \F_q} \overline{\psi(t \frac{dy-b}{a})} \ket{y}\nonumber\\
        &= \chi_{\beta}(a) \chi_{\alpha}(d) \psi(t \frac{b}{a}) \ket{v_{\frac{d}{a}t}}.
    \end{align}
    Thus $\ket{v_0}$ gives us another one-dimensional invariant subspace.
    \item The representation given by \cref{eq: principal series on basis} is equivalent to the one given in \cref{eq: rho_gamma action} after the basis change $\ket{v_t'} := \chi_{\beta^{-1}}(t)\ket{v_t}$ for all $t\in \F_q^*$. Indeed, the action on this basis is given by
    \begin{align*}
        I_{\alpha, \beta} \psm{a&b\\0&d} \ket{v_t'} &= \chi_{\beta^{-1}}(t) \chi_{\beta}(a) \chi_\alpha(d) \psi(t \frac{b}{a}) \ket{v_{\frac{d}{a}t}}\\
        &= \chi_{\alpha\beta}(d) \psi(t \frac{b}{a}) \chi_{\beta^{-1}}(t\frac{d}{a})\ket{v_{\frac{d}{a}t}}\\
        &= \chi_{\alpha\beta}(d)\psi(t \frac{b}{a}) \ket{v_{\frac{d}{a}t}'}.
    \end{align*}
\end{itemize}
Thus the Gelfand--Tsetlin basis for $I_{\alpha, \beta}$ is
\begin{align}\label{eq: GT principal}
    \{\ket{\infty}, \ket{v_0}, \ket{w_\delta}: \delta\in \F_q^*\}, \text{ with } \ket{w_\delta} &= \frac{1}{\sqrt{q-1}}\sum_{t\in \F_q^*} \chi_\delta(t)\chi_{\beta^{-1}}(t) \;\ket{v_t},\\
    \ket{v_t} &= \frac{1}{\sqrt{q}}\sum_{x\in \F_q} \overline{\psi(tx)}\;\ket{x}.\nonumber\end{align}

\paragraph{Steinberg and determinant representations}
We find a GT basis for both of these representations.
Recall from \cref{eq: v} the vector
\begin{equation}
    \ket{v}:= \frac{1}{\sqrt{q+1}}\left(\chi_{\alpha}(-1) \ket{\infty} + \sum_{x\in \F_q}\ket{x}\right) = \frac{1}{\sqrt{q+1}}\left(\chi_\alpha(-1)\ket{\infty} + \sqrt{q}\,\ket{v_0}\right)
\end{equation}
spans a one-dimensional subspace for the determinant representation, which is trivially subgroup adapted. The space of the Steinberg representation can then be spanned by
\begin{equation}
    \ket{v^\perp}:=\frac{1}{\sqrt{q+1}}\left(\sqrt{q}\,\chi_\alpha(-1)\ket{\infty} - \ket{v_0}\right) \text{ and } \ket{w_{\delta}}, \; \delta \in \F_q^*.
\end{equation}
Thus the GT basis for $(\chi_\alpha\circ\det)\oplus\St_\alpha$ is almost the same as for $I_{\alpha, \beta}$, but with a different combination of $\ket{\infty}$ and $\ket{v_0}$.

\paragraph{Cuspidal representations} The cuspidal representation $\pi_{\theta}$ is irreducible when restricted to $B$. The action on $\C[\F_q^*]$ is given by \cref{eq: cuspidal action}, which corresponds precisely to \cref{eq: rho_gamma action}. The Gelfand--Tsetlin basis is thus given by the multiplicative Fourier basis from \cref{eq: mult fourier basis}.

\subsection{Action of transversals}\label{sec: twiddle factors}
This subsection computes, in the Gelfand--Tsetlin bases fixed above, the representation matrices required by the two induction steps in the subgroup chain.
For \(T\subset B\), these are the matrices of all chosen transversal representatives.
For \(B\subset G\), the Mackey circuit of \cref{alg: Mackey induced transform} only requires the matrices of the nontrivial double-coset representative \(w\), since every non-identity transversal element has the form \(u_xw\) with \(u_x\in B\). We calculate the explicit coefficients for each irrep action at these transversal elements. The subsection also makes use of Gauss sums, which are defined in \cref{subsec: Gauss sums}.

\subsubsection{From \texorpdfstring{$T$}{T} to \texorpdfstring{$B$}{B}}\label{subsubsec: from T to B}
We only have to study the transversal actions for $\rho_\gamma$ defined in \cref{eq: rho_gamma action}, as the one-dimensional ones are already given above. The natural transversal set for $B/T$ is given by
\begin{equation*}
    u_b:= \psm{1&b\\0&1} \text{ for all } b \in \F_q.
\end{equation*}
The Gelfand--Tsetlin basis is given by \cref{eq: mult fourier basis}, on which the transversal set acts by
\begin{equation*}
    \rho_\gamma \psm{1&b\\0&1} \ket{w_\delta}
    =\frac{1}{\sqrt{q-1}}
      \sum_{x\in\F_q^*}\chi_\delta(x)\psi(bx)\ket{x}.
\end{equation*}
It follows that
\begin{align}\label{eq: twiddle factor B}
    \braket{w_\beta}{\rho_\gamma\psm{1&b\\0&1}| w_\alpha}
    &=\frac{1}{q-1}\sum_{x\in\F_q^*}
      \chi_{\alpha\beta^{-1}}(x)\psi(bx) \nonumber\\
    &=\frac{1}{q-1}G_q(\alpha\beta^{-1},b),
\end{align}
where $G_q$ is a Gauss sum, see \cref{def: Gauss sum} in \cref{subsec: Gauss sums}.

\subsubsection{From \texorpdfstring{$B$}{B} to \texorpdfstring{$G$}{G}}
The second set of transversal actions is a bit harder to compute. Using the transversal set of \cref{eq: transversal set G/B}, we can write each element as
\begin{equation*}
    t_x = \psm{1&x\\0&1} \cdot \psm{0&1\\1&0}.
\end{equation*}
Since the first part is an element of $B$, this will act as a block diagonal matrix on the Gelfand--Tsetlin basis, and the precise action is described in the previous section. In particular, we only have to study the representation action of the element $w=\psm{0&1\\1&0}$ on the Gelfand--Tsetlin basis. Since $w^2=\I$ it holds that $\braket{b'}{\rho(w)| b} = \overline{\braket{b}{\rho(w)| b'}}$ for any irreducible representation $\rho$ and normalized vectors $\ket{b},\ket{b'}$, so that we don't have to do some of the calculations double.

\paragraph{The principal series}\label{par: twiddle principal}
For the principal series, we can use \cref{eq: g action projective 1,eq: g action projective 2} to compute the transversal actions. On the initial basis, the action is given by
\begin{align*}
    &I_{\alpha, \beta} (w)\,\ket{0} = \ket{\infty}, \\
    &I_{\alpha, \beta} (w) \,\ket{\infty} = \ket{0}, \\
    &I_{\alpha, \beta} (w) \,\ket{x} = \chi_{\alpha}(x)\chi_{\beta}(-1/x)\ket{1/x} \quad \text{ for } x\in \F_q^*.
\end{align*}
We can then compute the inner product between basis elements to derive the explicit matrix. These derivations are done in \cref{app: twiddle calcs} and the resulting action for $I_{\alpha, \beta}$ with $\alpha\neq \beta$ is a sparse matrix given by the following.
\begin{itemize}
    \item The basis vectors $\{\ket{\infty}, \ket{v_0}, \ket{w_{\alpha}}, \ket{w_\beta}\}$ span an invariant subspace, where the action is given by
    \begin{align*}
I_{\alpha,\beta}(w)\ket{\infty} &= \frac{1}{\sqrt{q}}\ket{v_0} + \frac{\sqrt{q-1}}{\sqrt{q}}\ket{w_{\beta}},\\
I_{\alpha,\beta}(w) \ket{v_0} &=\frac{1}{\sqrt{q}}\ket{\infty} + \frac{\sqrt{q-1}}{q} \chi_{\beta}(-1)g_q(\alpha^{-1}\beta)\ket{w_\alpha},\\
I_{\alpha,\beta}(w) \ket{w_\alpha} &=\frac{\sqrt{q-1}}{q} \chi_{\beta^{-1}}(-1)\overline{g_q(\alpha^{-1}\beta)} \ket{v_0} + \frac{1}{q} \chi_{\alpha^{-1}}(-1) g_q(1) g_q(\alpha\beta^{-1}) \ket{w_{\beta}}\\
        &=\chi_{\alpha^{-1}}(-1)g_q(\alpha\beta^{-1})\left(\frac{\sqrt{q-1}}{q} \ket{v_0} - \frac{1}{q} \ket{w_{\beta}}\right),\\
I_{\alpha,\beta}(w) \ket{w_\beta} &= \frac{\sqrt{q-1}}{\sqrt{q}} \ket{\infty} - \frac{1}{q} \chi_{\beta^{-1}}(-1)g_q(\alpha^{-1}\beta) \ket{w_\alpha},
    \end{align*}
    where $g_q(\alpha) := G_q(\alpha,1)$ is a Gauss sum, see \cref{def: Gauss sum} in \cref{subsec: Gauss sums}.
    \item For the rest of the basis, consisting of $\{\ket{w_\delta}: \delta\notin\{\alpha,\beta\}\}$, the action by $I_{\alpha,\beta}$ is a phase-permutation matrix given by
    \begin{align*}
        I_{\alpha, \beta} (w) \ket{w_\delta}
        =\frac{1}{q}\chi_{\delta^{-1}}(-1)
        g_q(\delta\alpha^{-1})g_q(\delta\beta^{-1})
        \ket{w_{\alpha\beta\delta^{-1}}}.
    \end{align*}
\end{itemize}
Equivalently, for arbitrary $\delta,\epsilon\in X_q$,
\begin{equation}
 \langle w_\epsilon|I_{\alpha,\beta}(w)|w_\delta\rangle
 =\frac{1}{q}\chi_{\delta^{-1}}(-1)
   g_q(\delta\alpha^{-1})g_q(\delta\beta^{-1})
   \mathbf 1_{\{\epsilon=\alpha\beta\delta^{-1}\}}.
\end{equation}

\paragraph{Steinberg}\label{par: twiddle Steinberg}
The Steinberg and determinant representation are a little bit easier than the principal series. It holds that
\begin{align*}
    &I_{\alpha, \alpha} (w)\,\ket{0} = \ket{\infty}, \\
    &I_{\alpha, \alpha} (w) \,\ket{\infty} = \ket{0}, \\
    &I_{\alpha, \alpha} (w) \,\ket{x} = \chi_{\alpha}(-1)\ket{1/x},
\end{align*}
and indeed using the vector $\ket{v}$ from \cref{eq: v} we find that
\begin{equation*}
    I_{\alpha, \alpha}(w) \ket{v} = I_{\alpha, \alpha}(w) \frac{1}{\sqrt{q+1}} \left(\chi_{\alpha}(-1) \ket{\infty} + \sum_{x\in \F_q}\ket{x}\right) = \chi_{\alpha}(-1)\ket{v}
\end{equation*}
since $\chi_{\alpha}(-1)^2 = \chi_{\alpha}((-1)^2) = 1.$
On the GT basis for the Steinberg representation the action can be computed from the inner products in \cref{app: twiddle calcs}. We obtain
\begin{align*}
I_{\alpha, \alpha}(w)\ket{v^\perp} &=-\frac{1}{q}\chi_{\alpha}(-1)\ket{v^\perp}+ \chi_{\alpha}(-1)\frac{\sqrt{q^2-1}}{q}\ket{w_{\alpha}},\\
I_{\alpha, \alpha}(w)\ket{w_{\alpha}} &=\frac{\sqrt{q^2-1}}{q}\chi_{\alpha}(-1)\ket{v^\perp} + \frac{1}{q}\chi_{\alpha}(-1)\ket{w_{\alpha}},\\
\St_{\alpha}(w)\ket{w_{\delta}}
    &=\frac{1}{q}\chi_{\delta^{-1}}(-1)
      g_q(\delta\alpha^{-1})^2
      \ket{w_{\alpha^2\delta^{-1}}}
      \quad \text{for all } \delta\neq\alpha.
\end{align*}
For arbitrary $\delta,\epsilon\in X_q$, the coefficient between the $\rho_{\alpha^2}$ paths is
\begin{equation}\label{eq: corrected Steinberg matrix coefficient}
 \langle w_\delta|\St_\alpha(w)|w_\epsilon\rangle
 =\frac{\chi_{\epsilon^{-1}}(-1)}q
   g_q(\epsilon\alpha^{-1})^2
   \mathbf 1_{\{\delta=\alpha^2\epsilon^{-1}\}}.
\end{equation}

\paragraph{Cuspidal}
Next, consider a cuspidal representation $\pi_\theta$ with $\theta|_{\F_q^*}=\chi_\gamma$.  Its GT basis is the multiplicative Fourier basis of $\C[\F_q^*]$.  Since $w=w'\psm{-1&0\\0&1}$, equations \cref{eq: cuspidal action,eq: cuspidal w prime} give
\begin{align}
    \braket{w_\epsilon}{\pi_\theta(w)|w_\delta}
    &=-\frac{\chi_\delta(-1)}{q}
      g_{q^2}\!\left(\theta\cdot(\chi_{\epsilon^{-1}}\circ\No)\right)
      \mathbf 1_{\{\epsilon=\delta^{-1}\gamma\}}.
    \label{eq: corrected cuspidal twiddle}
\end{align}
Thus $\pi_\theta(w)$ permutes the GT basis by $\ket{w_\delta}\mapsto\ket{w_{\delta^{-1}\gamma}}$, with the displayed Gauss-sum phase. The minus sign comes from the normalization of $j_\theta$ in \cref{eq: cuspidal w prime}.

\subsection{The QFT circuit}\label{sec: GL2 QFT circuit}

\subsubsection{Fourier transforms of \texorpdfstring{$\F_q$}{Fq} and Gauss sums}
To construct a quantum circuit for the QFT of $G$, we must use the additive and multiplicative descriptions of a field element interchangeably.  Fix a generator $g\in\F_q^*$.  We write $\ket{a}_+$ when $a\in\F_q$ is stored in a polynomial-basis field encoding, and write $\ket{a}_\times$ when a nonzero element $a=g^d$ is stored by its exponent $d\in\Z/(q-1)\Z$.  A regime flag distinguishes these encodings; it is suppressed from the notation.  The state $\ket{0}_+$ is used as a zero element of the field and is never passed to a discrete-logarithm routine.

On nonzero basis states, define the representation-changing maps by
\begin{align}
    \exp_g\ket{g^d}_\times&=\ket{g^d}_+,
    \label{eq: exp operator}\\
    \log_g\ket{a}_+&=\ket{a}_\times.
    \label{eq: log operator}
\end{align}
They fix the zero and are extended to mutually inverse unitaries on the tagged work register.

\begin{lemma}\label{lem: add and mult of Fq}
    For every $\varepsilon>0$, there are uniform quantum circuits of size $\operatorname{poly}(\log q,\log(1/\varepsilon))$ which, with all ancillary registers returned to zero, implement to operator-norm error at most $\varepsilon$ the transforms
    \begin{align}
        \Fou_+\ket{x}_+
        &=
        \frac1{\sqrt q}\sum_{y\in\F_q}\psi_x(y)\ket{y}_+,
        \label{eq: efficient additive Fq QFT}\\
        \Fou_\times\ket{a}_\times
        &=
        \frac1{\sqrt{q-1}}\sum_{\alpha\in X_q}
        \chi_\alpha(a)\ket{\alpha}_\times,
        \qquad a\in\F_q^*,
        \label{eq: efficient multiplicative Fq QFT}
    \end{align}
    as well as the conversion maps \cref{eq: exp operator} and \cref{eq: log operator}.  The multiplicative transform is defined to fix $\ket{0}_+$.
\end{lemma}
\begin{proof}
    The additive transform is the QFT of the finite abelian group $(\F_q,+)$, with the trace pairing identifying $\F_q$ with its character group, and is efficiently implementable by \cite[Section~5]{Kitaev1995}.  The generator $g$ identifies $\F_q^*$ with the cyclic group $\Z/(q-1)\Z$, so the multiplicative transform is an efficient cyclic QFT.

    Reversible exponentiation implements $\exp_g$, while a reversible, amplified version of Shor's discrete-logarithm algorithm \cite{Shor1994, MoscaZalka2004} implements $\log_g$ to error at most $\varepsilon$ with clean ancillas in polynomial time.  The regime flag handles the zero element of the field without invoking discrete logarithm.
\end{proof}

Recall from \cref{def: Gauss sum} that a Gauss sum contains both an additive and multiplicative character. A quantum algorithm for Gauss sum estimation is given in \cite{vDS02} and was later reformulated in \cite{Bruin}. This latter version lends itself well to our purpose, and we present it here in an altered version. The algorithm makes use of an ancilla and requires the following operator.
\begin{lemma}[character phases]\label{lem: controlled character phase}
	The operator
    \begin{equation}
		U_{cp}\ket{\alpha}\ket{x}
        =\chi_\alpha(x)\ket{\alpha}\ket{x},
        \qquad \alpha\in X_q,\ x\in\F_q^*,
	\end{equation}
    and defined to be the identity when $\alpha=0$, can, for every $\varepsilon>0$, be implemented to operator-norm error at most $\varepsilon$ with size $\operatorname{poly}(\log q,\log(1/\varepsilon))$.
\end{lemma}
\begin{proof}

    Put $N=q-1$ and $\omega_N=e^{2\pi i/N}$.  In the exponent encodings, let $k,d\in\Z/N\Z$ be the stored labels of $\chi_\alpha$ and $x=g^d$, respectively, with the convention $\chi_\alpha(g^d)=\omega_N^{kd}$.  We apply the phase kickback trick.  Prepare a register
    \begin{equation*}
        \ket{\widetilde 1}
        =\frac1{\sqrt N}\sum_{s\in\Z/N\Z}\omega_N^{-s}\ket{s}
    \end{equation*}
    via inverse additive Fourier transform. Reversibly compute $t=kd\bmod N$ in a clean register and add $t$ modulo $N$ to the $\ket{\widetilde{1}}$ register.  Since
    \begin{equation*}
        \operatorname{Add}_t\ket{\widetilde 1}
        =\omega_N^t\ket{\widetilde 1},
    \end{equation*}
    this multiplies the input by $\omega_N^{kd}=\chi_\alpha(x)$ without changing either input register.
    Uncomputing $t$ and unpreparing $\ket{\widetilde 1}$ returns all ancillas to zero. Note that the regime flag bypasses the entire construction on the zero element.
\end{proof}

\begin{theorem}[Gauss phase]\label{thm: coherent Gauss phase}
	\sloppy For every $\varepsilon>0$ there is a circuit over $\C[\F_q]$ of size $\operatorname{poly}(\log q,\log(1/\varepsilon))$ that is $\varepsilon$-close in operator norm to
	\begin{equation}\label{eq: coherent Gauss phase}
		\Gamma_q\ket{\alpha}=\begin{cases}
			\ket{0}, & \alpha=0,\\
			-\ket{1}, & \alpha=1,\\
			\dfrac{g_q(\alpha)}{\sqrt{q}}\ket{\alpha},
            & \alpha\in X_q\setminus\{1\}.
		\end{cases}
	\end{equation}
\end{theorem}

\begin{proof}
    First detect the zero using the regime flag.  On that branch perform no operation, so $\Gamma_q\ket{0}=\ket{0}$.  On the multiplicative branch, apply the phase $-1$ conditional on $\alpha=1$.
    For $\alpha\in X_q\setminus\{1\}$, initialize a work register in the multiplicative identity state and apply the following circuit:
    \input{figures/circuits/gl2_gauss_phase}
    Each $U_{cp}$ acts jointly on the displayed registers and leaves the $\alpha$-register unchanged.
    After the first controlled phase, exponentiation, and the additive Fourier transform, the work state is
    \begin{equation*}
      \frac1{\sqrt{q(q-1)}}
      \sum_{y\in\F_q}
      \left(\sum_{x\in\F_q^*}\chi_\alpha(x)\psi(xy)\right)|y\rangle_+.
    \end{equation*}
    The coefficient at $y=0$ vanishes.  For $y\neq0$ the substitution $z=xy$ gives
    \begin{equation*}
      \sum_{x\in\F_q^*}\chi_\alpha(x)\psi(xy)
      =\chi_{\alpha^{-1}}(y)g_q(\alpha).
    \end{equation*}
    Hence the work state is
    \begin{equation*}
      \frac{g_q(\alpha)}{\sqrt q}\,
      \frac1{\sqrt{q-1}}
      \sum_{y\in\F_q^*}\chi_{\alpha^{-1}}(y)|y\rangle_+.
    \end{equation*}
    The logarithm and second controlled phase cancel $\chi_{\alpha^{-1}}(y)$, and $\Fou_\times^\dagger$ returns the work register to its initial state.  Since $|g_q(\alpha)|=\sqrt q$, the remaining factor is a phase.  Every gate in this sequence is controlled on the nonzero regime flag, so the zero sentinel is unchanged and is never passed to $\log_g$ or $\exp_g$.  The error bound follows from \cref{lem: add and mult of Fq} and composition of a constant number of approximate unitaries.
\end{proof}

\subsubsection{Circuit for the QFT of \texorpdfstring{$B$}{B}}
A circuit for the QFT of $B$ uses three input registers for $a,d\in \F_q^*$ and $b\in \F_q$. Together they encode the group element $g(a,d,b) = \psm{1&b\\0&1}\psm{a&0\\0&d}$. We will use a naive encoding for the Fourier register, so some clean registers are needed. For labeling the representation of $B$ we use $\C[\F_q]^{\otimes3}$, where $\ket{0, \alpha,\beta}$ labels the linear representation $\chi_{\alpha,\beta}$ and $\ket{\gamma, 0,0}$ labels $\rho_\gamma$.
\begin{itemize}
	\item Start with an input state $\ket{a,d}\ket{b}$ and clean register $\ket{0,0}\ket{0,0}$. Assume that $\ket{b} = \ket{b}_+$ is encoded additively. The total starting state is then
	\begin{equation*}
		\ket{a,d}\ket{b,0,0}\ket{0,0},
	\end{equation*}
	which will be transformed into the Fourier basis with basis states of the form $\ket{\chi}\ket{\lambda}\ket{\tilde{\chi}}$.
	\item Perform the QFT over $T$ on the first two registers.
	\item Apply $\Fou_+$ over the $b$-register, followed by $\log_g$ and $\Fou_{\times}$. Ignoring the clean register in notation, we obtain the state
	\begin{align*}
		&\frac{1}{(q-1)\sqrt{q}}\sum_{\alpha, \beta\in X_q} \chi_{\alpha}(a)\chi_{\beta}(d)\left(\ket{\alpha,\beta}\ket{0}_+ + \frac{1}{\sqrt{q-1}}\sum_{\substack{t\in \F_q^*\\ \eta\in \F_q^*}}\psi(bt)\chi_{\eta}(t) \ket{\alpha, \beta}\ket{\eta}_{\times}\right).\\
		=&\frac{1}{(q-1)\sqrt{q}}\sum_{\alpha, \beta\in X_q} \chi_{\alpha}(a)\chi_{\beta}(d)\left(\ket{\alpha,\beta}\ket{0}_+ + \frac{1}{\sqrt{q-1}}\sum_{\substack{t\in \F_q^*\\ \delta\in \F_q^*}}\psi(bt)\chi_{\alpha\delta^{-1}}(t) \ket{\alpha, \beta}\ket{\alpha\delta^{-1}}_{\times}\right).
	\end{align*}

	\item Lastly, we need to use arithmetic over finite fields to reorder all the information into the correct registers. Specifically, we apply the following transformations
	\begin{align}
		\label{eq: Ub twid first} \operatorname{U_{B, transv}}: &\ket{\alpha, \beta}\ket{0,0,0} \ket{0,0}\mapsto \ket{\alpha, \beta}\ket{0,\alpha,\beta} \ket{\alpha,\beta}\\
		&\label{eq: Ub twid sec}\ket{\alpha,\beta}\ket{ \alpha\delta^{-1},0,0}\ket{0,0} \mapsto \ket{\alpha,\beta}\ket{\alpha\beta, 0, 0}\ket{\delta, \delta^{-1}\alpha\beta}
	\end{align}
\end{itemize}
The quantum circuit looks as follows.
\input{figures/circuits/gl2_borel_qft}
\begin{remark}
	The first two registers undergo the Fourier transform of $T \cong (\F_q^*)^2$.
\end{remark}

\begin{lemma}
	The operator $\operatorname{U_{B, transv}}$ can be efficiently implemented.
\end{lemma}
\begin{proof}
	Recall that the register for $\F_q$ actually contains three parts. One for both its additive and multiplicative structure, and an indicator which of the two you need to look at.

	When the control qubit is $0$, it is in the additive structure and can be ignored by $\operatorname{U_{B, transv}}$. The operation we then need to perform is to duplicate $\ket{\alpha, \beta}$ into a clean register as in \cref{eq: Ub twid first}

	When the control qubit is 1, we have performed $\Fou_\times$ and we are in the multiplicative part of the register. We can therefore view $\operatorname{U_{B, twid}}$ as an operator on $\C[\F_q^*]^{\otimes 5}$, leaving the additive part of $\C[\F_q]$ alone and also ignoring the other two parts of the middle. Write $\alpha = g^a, \beta = g^b, \delta = g^d$ and using the identification $\F_q^* \cong \Z/(q-1)\Z$ we need to construct an operator $U_{B, \operatorname{transv}}'$ that maps
	\begin{equation*}\ket{a, b} \ket{a-d,0,0}\ket{0,0}
    \mapsto \ket{a,b}\ket{a+b,0,0}\ket{d,a+b-d}.\end{equation*}
	This is efficiently implementable by \cite{beauregard2003quantum}.
\end{proof}

\begin{theorem}
\label{thm: efficient B QFT}
	For every $\varepsilon>0$, there is a quantum circuit of size $\operatorname{poly}(\log q,\log(1/\varepsilon))$ that implements the Fourier transform $\Fou_B$ of
	\begin{equation}
		B=\left\{\psm{a&b\\0&d}:a,d\in\F_q^*,\ b\in\F_q\right\}
	\end{equation}
	in the representation bases fixed above, to operator-norm error at most $\varepsilon$.
\end{theorem}
\begin{proof}
	The calculation above and \cref{fig: GL2 B QFT decomposition} express $\Fou_B$ as two multiplicative Fourier transforms implementing $\Fou_T$, followed by one additive Fourier transform, the conversion $\log_g$, a third multiplicative Fourier transform, and the relabeling $U_{B,\mathrm{twid}}$.  By \cref{lem: add and mult of Fq}, each Fourier transform and $\log_g$ has a uniform circuit of size $\operatorname{poly}(\log q,\log(1/\varepsilon))$.  The preceding lemma provides an efficient implementation of $U_{B,\mathrm{twid}}$.
\end{proof}

\subsubsection{The untwisting map}

For the Mackey circuit associated with $B\subseteq G$, the Bruhat decomposition gives the two double-coset representatives $e$ and $w$, with
\begin{equation*}
	H_e=B,\qquad H_w=B\cap wBw^{-1}=T.
\end{equation*}
The identity representative gives $\U_{\tw}^e=I$.  For the non-trivial cell, $w^{-1}Tw=T$ and
\begin{equation*}
	w^{-1}\psm{a&0\\0&d}w=\psm{d&0\\0&a},
\end{equation*}
so we are in the normalizer situation of \cref{subsec: omega normalizes}.  Twisting therefore does not require a new irreducible decomposition: it only permutes the characters of $T$ by
	\begin{equation*}
	\chi_{\alpha,\beta}^w=\chi_{\beta,\alpha}.
	\end{equation*}

In particular, using $\Res_T^B\rho_\gamma=\bigoplus_{\delta\in X_q} \chi_{\delta,\delta^{-1}\gamma}$ from \cref{lem: decomposition of restrictions}, the $\delta$-summand is sent to the $\delta^{-1}\gamma$-summand.  With the one-dimensional block intertwiners chosen to be the identity, the untwisting operator is the permutation
\begin{equation}
	\U_{\tw}^w\ket{w_\delta}
	=\ket{\chi_{\delta^{-1}\gamma,\delta}}.
	\label{eq: GL2 untwisting convention}
\end{equation}
Equivalently, setting $\delta=\alpha^{-1}\gamma$ gives $\U_{\tw}^w\ket{w_{\alpha^{-1}\gamma}} =\ket{\chi_{\alpha,\alpha^{-1}\gamma}}$.
Thus $\U_{\tw}$ is implemented exactly by a cell-controlled swap of the two character coordinates, or by the reversible character operation $\delta\mapsto\delta^{-1}\gamma$ on a $\rho_\gamma$-path.  Its circuit size is polynomial in $\log q$.

\subsubsection{Circuit for the \texorpdfstring{$A$}{A}-matrix}

The hardest part of the circuit to implement is the $A$-matrix.  We use the double-coset and untwisting conventions from the previous subsection.
Fix a total order $\prec$ on $X_q$ and represent a principal series by $I_{\alpha,\beta}$ with $\alpha\prec\beta$.
Define the unit-modulus phase
\begin{equation}\label{eq: mixed A phase}
    \zeta_{\alpha,\beta}
    :=\chi_\beta(-1)\frac{g_q(\alpha^{-1}\beta)}{\sqrt q}.
\end{equation}
Recall from \cref{def: Mackey operators} that the $A$-matrix is block diagonal, depending on the inputs $\lambda$ and $\widetilde{\lambda}$ and given by
\begin{equation*}
A=\sum_{\lambda,\widetilde\lambda\in\widehat B}
\ket{\lambda}\!\bra{\lambda}\otimes
A_{\lambda,\widetilde\lambda}\otimes
\ket{\widetilde\lambda}\!\bra{\widetilde\lambda}.
\end{equation*}
For most pairs $(\lambda, \widetilde\lambda)$ the multiplicity space is one- or two-dimensional.
Each display below specifies one block $A_{\lambda, \widetilde\lambda}$. Its source basis is labeled $\ket{\kappa, \omega}$, where $\kappa$ is an intermediate character and $\omega$ a double coset representative. Note that the same $\ket{\kappa, \omega}$ can appear in several blocks.
\begin{align}
 &A_{\chi_{\alpha,\beta}, \chi_{\alpha, \beta}}|\chi_{\alpha,\beta},e\rangle
    \longmapsto |I_{\alpha,\beta}\rangle,
    &&\alpha\prec\beta,\\
 &A_{\chi_{\alpha,\beta}, \chi_{\beta, \alpha}}|\chi_{\beta,\alpha},w\rangle
    \longmapsto |I_{\alpha,\beta}\rangle,
    &&\alpha\prec\beta,\\
 &A_{\chi_{\alpha,\alpha}, \chi_{\alpha, \alpha}}|\chi_{\alpha,\alpha},e\rangle
    \longmapsto
      \sqrt{\frac q{q+1}}|\St_\alpha\rangle
      +\frac1{\sqrt{q+1}}|\det_\alpha\rangle,\\
 &A_{\chi_{\alpha,\alpha}, \chi_{\alpha, \alpha}}|\chi_{\alpha,\alpha},w\rangle
    \longmapsto
      \chi_\alpha(-1)\left(
      -\frac1{\sqrt{q+1}}|\St_\alpha\rangle
      +\sqrt{\frac q{q+1}}|\det_\alpha\rangle\right).
\end{align}
For $\alpha\prec\beta$, the mixed blocks are
\begin{align}
 A_{\chi_{\alpha,\beta},\rho_{\alpha\beta}}:
 |\chi_{\beta,\alpha},w\rangle
    &\longmapsto |I_{\alpha,\beta}\rangle,\\
 A_{\chi_{\beta,\alpha},\rho_{\alpha\beta}}:
 |\chi_{\alpha,\beta},w\rangle
    &\longmapsto \zeta_{\alpha,\beta}|I_{\alpha,\beta}\rangle,\\
 A_{\rho_{\alpha\beta},\chi_{\alpha,\beta}}:
 |\chi_{\alpha,\beta},w\rangle
    &\longmapsto |I_{\alpha,\beta}\rangle,\\
 A_{\rho_{\alpha\beta},\chi_{\beta,\alpha}}:
 |\chi_{\beta,\alpha},w\rangle
    &\longmapsto \overline{\zeta_{\alpha,\beta}}
       |I_{\alpha,\beta}\rangle.
\end{align}
The cases where $\alpha=\beta$ are
\begin{align}
 A_{\chi_{\alpha,\alpha},\rho_{\alpha^2}}:
 |\chi_{\alpha,\alpha},w\rangle
    &\longmapsto\chi_\alpha(-1)|\St_\alpha\rangle,\\
 A_{\rho_{\alpha^2},\chi_{\alpha,\alpha}}:
 |\chi_{\alpha,\alpha},w\rangle
    &\longmapsto\chi_\alpha(-1)|\St_\alpha\rangle.
\end{align}
It remains to describe $A_{\rho_\gamma,\rho_\gamma}$.  Its rows are indexed by
\begin{align}
 \mathcal C_\gamma
   &=\{\{\theta,\theta^q\}:\theta^q\neq\theta,
       \ \theta|_{\F_q^*}=\chi_\gamma\},\\
 \mathcal P_\gamma
   &=\{\{\delta,\eta\}:\delta\eta=\gamma,\ \delta\neq\eta\},\\
 \mathcal S_\gamma
   &=\{\delta:\delta^2=\gamma\},
\end{align}
corresponding respectively to paths via $\pi_\theta$, $I_{\delta,\eta}$, and $\St_\delta$.  If $s_\gamma=|\mathcal S_\gamma|$, then
\begin{equation*}
 |\mathcal C_\gamma|=\frac{q+1-s_\gamma}{2},\qquad
 |\mathcal P_\gamma|=\frac{q-1-s_\gamma}{2},\qquad
 |\mathcal S_\gamma|=s_\gamma,
\end{equation*}
so these sets contain exactly $q$ labels in total.  Write
\begin{equation}
\label{eq: A_gamma col indexing}
\ket{c_\infty}:=\ket{\rho_\gamma,e},
 \qquad
 \ket{c_\alpha}:=\ket{\chi_{\alpha,\alpha^{-1}\gamma},w},
 \quad \alpha\in X_q.
\end{equation}
Using the generator $g$ fixed above, identify $X_q$ with $\F_q^*$ by matching exponent labels and regard this source basis as one $\F_q$-register via $\ket{c_\infty}\leftrightarrow\ket{0}$ and $\ket{c_\alpha}\leftrightarrow\ket{\alpha}$.  The first identification is canonical and the nonzero identification uses the fixed generator.
The first column (corresponding to the $\ket{0}$-input) is
\begin{align}
 A_{\rho_\gamma,\rho_\gamma}\ket{c_\infty}
  ={}&\frac1{\sqrt{q+1}}
       \sum_{\{\theta,\theta^q\}\in\mathcal C_\gamma}|\pi_\theta\rangle
   +\frac1{\sqrt{q-1}}
       \sum_{\{\delta,\eta\}\in\mathcal P_\gamma}|I_{\delta,\eta}\rangle
       \nonumber\\
   &+\sqrt{\frac q{(q-1)(q+1)}}
       \sum_{\delta\in\mathcal S_\gamma}|\St_\delta\rangle.
 \label{eq: corrected A identity column}
\end{align}
For the other columns, put $b=\alpha^{-1}\gamma$. Then the $A$-matrix acts as
\begin{align}
 A_{\rho_\gamma,\rho_\gamma}\ket{c_\alpha}
 ={}&-\frac{\chi_b(-1)}{\sqrt{q(q^2-1)}}
       \sum_{\{\theta,\theta^q\}\in\mathcal C_\gamma}
       g_{q^2}\!\left(\theta\cdot(\chi_{\alpha^{-1}}\circ\No)\right)
       |\pi_\theta\rangle
       \nonumber\\
 &+\frac{\chi_b(-1)}{(q-1)\sqrt q}
       \sum_{\{\delta,\eta\}\in\mathcal P_\gamma}
       g_q(\alpha^{-1}\delta)g_q(\alpha^{-1}\eta)
       |I_{\delta,\eta}\rangle
       \nonumber\\
 &+\frac{\chi_b(-1)}{(q-1)\sqrt{q+1}}
       \sum_{\delta\in\mathcal S_\gamma}
       g_q(\alpha^{-1}\delta)^2|\St_\delta\rangle.
 \label{eq: corrected A nontrivial column}
\end{align}

The first sum is independent of the chosen representative of the orbit $\{\theta,\theta^q\}$ because the norm character is invariant under Frobenius, and the substitution $z\mapsto z^q$ leaves the $\F_{q^2}$ Gauss sum unchanged.
These coefficients follow from \cref{eq: corrected general A coefficient} and the transversal actions computed above. Note that we don't have to check unitarity as this also follows from \cref{thm: Mackey induced circuit}.

All blocks other than $A_{\rho_\gamma,\rho_\gamma}$ have dimension at most two and are implementable in $\operatorname{poly}(\log q)$ gates using reversible character arithmetic, one controlled rotation, and the Gauss phase of \cref{thm: coherent Gauss phase}.
The hardest part is given by the $q\times q$-unitary from \cref{eq: corrected A identity column,eq: corrected A nontrivial column}.  Treating this unitary as an unstructured matrix and synthesizing it by Givens rotations would cost $O(q^2\operatorname{poly}(\log q,\log(1/\varepsilon)))$ gates for each fixed $\gamma$ \cite[Section~4.5]{NielsenChuang}.  An efficient way to construct these bigger blocks is treated in the next subsection.

\begin{theorem}[Efficient implementation of the total $A$-matrix]
\label{thm: efficient GL2 total A matrix}
	For every $\varepsilon>0$, the total $A$-matrix in the Mackey circuit for $B\subseteq\GL_2(\F_q)$ has an implementation to operator-norm error at most $\varepsilon$ using $\operatorname{poly}(\log q,\log(1/\varepsilon))$ gates.
\end{theorem}
\begin{proof}
	Recall from \cref{def: Mackey operators} that the total operator is the controlled direct sum
	\begin{equation*}
		A=\sum_{\lambda,\widetilde\lambda\in\widehat B}
		\ket{\lambda}\!\bra{\lambda}\otimes
		A_{\lambda,\widetilde\lambda}\otimes
		\ket{\widetilde\lambda}\!\bra{\widetilde\lambda}.
	\end{equation*}
	The registers entering $A$ also contain the double-cell label $\omega$ and the intermediate character label $\kappa$.  From $(\lambda,\widetilde\lambda,\kappa,\omega)$ we reversibly compute a control indicating which of the block families displayed above applies.  The required tests consist only of distinguishing a one-dimensional label $\chi_{\alpha,\beta}$ from a label $\rho_\gamma$, comparing character labels, and computing their products and inverses. This gives a fixed size of the control register and the checks therefore use $\operatorname{poly}(\log q)$ gates.

	On the one- and two-dimensional families, the formulas above are implemented by reversible relabeling, the phases $\chi_\alpha(-1)$ and $\zeta_{\alpha,\beta}$, and the displayed two-dimensional determinant--Steinberg rotation.  Character arithmetic is reversible, the Gauss-sum factor in $\zeta_{\alpha,\beta}$ follows from \cref{thm: coherent Gauss phase}, and the rotation can be synthesized with $\operatorname{poly}(\log q,\log(1/\varepsilon))$ gates.
	Assigning a sufficiently small constant fraction of $\varepsilon$ to each approximate primitive makes every such block $\varepsilon$-accurate.
	The only remaining family is $A_{\gamma}:=A_{\rho_\gamma,\rho_\gamma}$.  By \cref{thm: efficient GL2 hard A circuit} below, a single circuit implements this $q\times q$ block with $\gamma$ retained in its label register as a control.  Thus the construction does not iterate over the $q-1$ possible values of $\gamma$.

	Apply the circuits for these constantly many families controlled by the block tag and then uncompute the tag.
\end{proof}

\subsection{The \texorpdfstring{$A_\gamma$}{A-gamma}-block}
\label{subsec: polylog GL2 A}

The $A_{\gamma}$ blocks are the only blocks in the $A$-matrix whose dimension grows with $q$.  For fixed $\gamma$, the input basis is $\ket{c_\infty},\ket{c_\alpha}$, $\alpha\in X_q$, and the target basis is indexed by $\mathcal C_\gamma,\mathcal P_\gamma,\mathcal S_\gamma$, as above.  We will show that there exists an efficient circuit producing the matrix columns in \cref{eq: corrected A identity column,eq: corrected A nontrivial column}. Recall that the columns of $A_\gamma$ are indexed by \cref{eq: A_gamma col indexing}, while its rows are indexed by the irreps of $G$.

\begin{remark}
When $q=2$, necessarily $\gamma=1$.  The set $\mathcal C_1$ consists of the unique nontrivial Frobenius orbit $\{\theta,\theta^2\}\subset X_4$, while $\mathcal P_1=\varnothing$ and $\mathcal S_1=\{1\}$.  Moreover, $g_2(1)=-1$ and, with the convention of \cref{def: Gauss sum}, $g_4(\theta)=2$.  Indeed, if $u$ generates $\F_4^*$, then $\tr(1)=0$, $\tr(u)=\tr(u^2)=1$, and $\theta(u)+\theta(u^2)=-1$, so $g_4(\theta)=1-\theta(u)-\theta(u^2)=2$.  Therefore \cref{eq: corrected A identity column,eq: corrected A nontrivial column} give, in the ordered source basis $(\ket{c_\infty},\ket{c_1})$ and target basis $(\ket{\pi_\theta},\ket{\St_1})$,
\begin{equation}
	A_1=
	\begin{pmatrix}
		1/\sqrt3&-\sqrt{2/3}\\
		\sqrt{2/3}&1/\sqrt3
	\end{pmatrix}.
	\label{eq: GL2 q2 hard A block}
\end{equation}
This constant-size rotation can be synthesized directly.  Hence, for the remainder of this subsection we may assume that $q>2$.
\end{remark}

Looking at \cref{eq: corrected A identity column,eq: corrected A nontrivial column}, for each input state we need to create a superposition over the same three sums, where the normalization is slightly different for the special symbol input $\ket{c_{\infty}}$. Beyond creating this superposition, we also need to add local phases that depend on the input. The total circuit will look as follows and we briefly explain the role of each gate.
\input{figures/circuits/gl2_hard_a_block}
\begin{itemize}
	\item The gate $D_\gamma$ adds a Gauss-sum phase. This is a diagonal gate and does not work toward creating the correct superposition.
	\item Fourier transform changes the input character label into a sum of field elements $t$.
	\item This sum over $t$'s we will divide into two routes by looking at the polynomial $X^2-X+t$. If the polynomial splits over $\F_q$, we call it the split case and these will become the principal series. If the polynomial is irreducible, we call it non-split and they contribute to cuspidal representations. The gate $B_{\gamma}$ sends the $t$'s to their correct groups.
	\item After the branching, we apply a Fourier transform on both branches to help create the correct superposition and phases.
	\item On each branch, i.e. split and non-split, labels need to be combined into the correct representation. The idea of this step is that the principal series $I_{\alpha, \beta}$ and $I_{\beta, \alpha}$ are the same representation and thus need the same label. Similarly, $\pi_{\theta}$ and $\pi_{\theta^q}$ need the same label. The gate $R_{\mathrm{fix}, \gamma}$ fixes these labels.
	\item Lastly, the gate $R_{\mathrm{exc}, \gamma}$ deals with the exceptional (or edge) cases, i.e. when $\alpha = \beta$ for the principal series, to ensure these end up with the correct phases and normalization. Note that for even characteristic, the edge cases will be slightly different and no repeated root can occur.
\end{itemize}

The branching gate maps a $q$-dimensional input space into a larger labeled space.  We therefore use extra registers and extend its action to a unitary on the full register.  All equalities below are for inputs with these extra registers in the zero state.
In the next subsections we give formal definitions of all the gates, show that they form a circuit for $A_\gamma$, and prove that each gate is efficiently implementable.

\subsubsection{Definition of the gates}

For the rest of the subsection, when the input is $\ket{c_\alpha}$, write $b=\alpha^{-1}\gamma$ as in \cref{eq: corrected A nontrivial column}.

\begin{definition}[The phase gate]
	Define
	\begin{align}
		D_\gamma\ket{c_\infty}&=\ket{c_\infty},\\
		D_\gamma\ket{c_\alpha}
		&=\begin{cases}
			\displaystyle
			\chi_b(-1)\frac{g_q(\alpha^{-1}b)}{\sqrt q}\ket{c_\alpha}
			&\alpha\ne b,\\[2mm]
			\ket{c_\alpha}&\alpha=b.
		\end{cases}
		\label{eq: GL2 generic diagonal}
	\end{align}
\end{definition}
If $\alpha\ne b$, then $\alpha^{-1}b$ is nontrivial and the coefficient in \cref{eq: GL2 generic diagonal} has absolute value one.  Thus $D_\gamma$ is unitary.

\begin{definition}
The gate $\Fou_\times^\dagger$ is the inverse Fourier transform, i.e. the adjoint of \cref{eq: efficient multiplicative Fq QFT}. It fixes $\ket{c_\infty}=\ket0$.
\end{definition}

To define the branching gate, we fix the character coordinates used on the nonsplit branch.  Let $h$ generate $\F_{q^2}^*$ such that $g=h^{q+1}$ is the generator of $\F_q^*$ fixed at the start of the section.
The map $z\mapsto z/z^q$ gives an identification $\F_{q^2}^*/\F_q^*\simeq\ker\No.$ If $\chi_\gamma(g)=e^{2\pi i k/(q-1)}$ for some $0\leq k\leq q-2$, choose $\theta_0$ by
\begin{equation*}
 \theta_0(h)=e^{2\pi i k/(q^2-1)}
\end{equation*}
so that $\theta_0|_{\F_q^*}=\chi_\gamma$.  Every character of $\F_{q^2}^*$ restricting to $\chi_\gamma$ is uniquely of the form $\theta_0\nu$ for some $\nu\in\widehat{\ker\No}$ pulled back along $z\mapsto z/z^q$.  Using these coordinates, Frobenius acts by
\begin{equation}
