 \label{eq: GL2 affine Frobenius coordinate}
\end{equation}

\begin{definition}[The quadratic branching gate] Define the branching map $B_{\gamma}: \C[\F_q] \to \C^2\otimes \C[\F_{q^2}^*]$, given by
\begin{equation} \label{eq: GL2 split router}
